  CONSTRAINT `fk_factura_vendedor` FOREIGN KEY (`id_vendedor`) REFERENCES `vendedor` (`id_vendedor`)
) ENGINE=InnoDB AUTO_INCREMENT=32766 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
